(() => {
  const form = document.querySelector('form');
  const els = form.querySelectorAll('button,input,select,textarea,[contenteditable="true"],[role="button"],[role="combobox"],a');
  const out = [];
  els.forEach(el => {
    const t = (el.innerText||'').trim().replace(/\n+/g,' / ').slice(0,60);
    if (el.tagName==='A' && !el.getAttribute('aria-label') && !t) return;
    out.push([el.tagName, el.id||'', el.getAttribute('aria-label')||'', el.getAttribute('placeholder')||'', t].join(' | '));
  });
  return out.slice(0,120);
})()

