(() => {
  const cd = document.querySelector('.inline-edit--container.combinedDate');
  const st = document.querySelector('.inline-edit--container.status');
  const desc = document.querySelector('.inline-edit--container.description');
  const assignee = document.getElementById('wp-new-inline-edit--field-assignee');
  const outline = (root, depth) => {
    if(!root) return 'MISSING';
    const walk = (el, d) => {
      let s = ' '.repeat(d) + el.tagName + (el.id ? '#'+el.id : '') + '.' + ((el.className||'').toString().split(' ').filter(Boolean).slice(0,3).join('.'));
      const a = el.getAttribute('aria-label'); if (a) s += ' [aria='+a.slice(0,40)+']';
      if (el.tagName==='INPUT') s += ' ph='+(el.getAttribute('placeholder')||'')+' val='+el.value;
      s += '\n';
      if (d < depth) [...el.children].forEach(c=> s += walk(c, d+1));
      return s;
    };
    return walk(root,0);
  };
  return {combinedDate: outline(cd,3), status: outline(st,2), desc: outline(desc,2), assignee: outline(assignee,2)};
})()

